		public void OnFindSeqCommand_ContestHensin() {
			int targetIndex = 0;
			if (userIndex == 0)
			{
				int count = 0;
				do
				{
					targetIndex = UnityEngine.Random.Range(0, 4);
					if (count > 18)
						break;

					count++;
				}
				while (userIndex == targetIndex);
			}

			ContestPlayerEntity entity = playerEntityArray[targetIndex];
			if (entity == null)
				return;

			entity.CreateCopyModel(pokemonContent);
			specialWazaModelPtr = entity.WazaPokemon;
			BattlePokemonEntity pokeEntity = specialWazaModelPtr.Entity;
			pokeEntity.Initialize(entity.Catalog, true);
			specialWazaModelPtr.Initialize((BtlvPos)entity.Index, entity.PlayerData.pokemonInfo.pokeParam);
			pokeEntity.PokeAnimSoundEnable = true;
			pokeEntity.SetRenderActive(false);
		}
		public void PerformContestWaza_Hensin() {
			if (specialWazaModelPtr == null)
				return;

			ContestPlayerEntity userEntity = playerEntityArray[userIndex];
			if (tempWazaModelPtr == null)
				tempWazaModelPtr = userEntity.WazaPokemon;

			userEntity.ReplaceWazaPokemon(specialWazaModelPtr);
		}
