		public void EmitVisualHeart(int playerIndex) {
			Vector2 emitPos = Vector2.zero;
			emitPos.y = contestSetting.visualHeartParam.posY;
			float halfWidth = Screen.width * 0.5f;
			emitPos.x = halfWidth + ((playerIndex % 2 == 0) ? halfWidth * -0.5f : halfWidth * 0.5f);

			AContestPlayerData playerData = playerEntityArray[playerIndex].PlayerData;
			// PlayerVisualDataModel.IsEmitHeart inlined (normal > 0 || large > 0)
			if (playerData.visualDataModel.IsEmitHeart)
				ContestSoundPlayer.player.PlaySeByID(ContestSoundPlayer.PlaySE_ID.PokeHeartL);

			heartEmitter.CreateVisualHeartFx(playerData.visualDataModel.emitLargeHeartNum, emitPos, true);
			heartEmitter.CreateVisualHeartFx(playerData.visualDataModel.emitNormalHeartNum, emitPos, false);
		}
